import json,copy
from pathlib import Path
R=Path(__file__).resolve().parents[1]
def read(p):return json.loads((R/p).read_text())
def write(p,d):(R/p).write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
def node(id,title,drug,text,x,y):return [id,title,drug,text,x,y]
def schedule(title,columns,rows,note,sources):return dict(title=title,columns=columns,rows=[dict(label=a,cells=b) for a,b in rows],note=note,source_ids=sources)
