 profiles[c]['monitoring_schedule']=schedule('Ribociclib: checks before starting and within the early cycles',['Before first dose','Cycle 1 Day 14','Cycle 2 · start and Day 14','Cycles 3–6 · before each','Later cycles'],[('Blood count / liver / renal',['Baseline','Two-week check','Continue two-weekly checks','Before each cycle','As clinically indicated; agree the local plan']),('ECG · heart rhythm',['Required; assess QTcF','Repeat around Day 14','If clinically indicated','If clinically indicated','If symptoms, QT concerns or interacting medicines']),('Electrolytes',['Baseline; correct abnormalities','Additional tests if indicated','At start of cycle','At start of each cycle','As clinically indicated']),('Restart review',['Confirm prescription and interactions','Review results; hold if required','No automatic restart','Optional local D25–26 review window','Team confirms each hold / restart plan'])],'Days 1–21: ribociclib. Days 22–28: break. The endocrine partner follows its own schedule. Day 25–26 is a local operational option, not an NCCP replacement for early checks.',['nccp','ribo'])
